    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the interface id; the property: when interfaceId == type(IAccessControl).interfaceId,
    // reference returns true, mutant returns false. We let fuzzer supply the id.
    function testFuzz_property(bytes4 interfaceId) public {
        // No strong assumptions — keep domain wide so fuzzer can pick the deciding interfaceId
        // Call supportsInterface and capture whether it returns (no revert) and the boolean result
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool res) {
            ok = res;
        } catch {
            // Shouldn't revert; if it does, treat as false
            ok = false;
        }

        // The general rule we assert: if the supplied interfaceId equals IAccessControl's id,
        // the reference implementation returns true. This will fail on the mutant for that id.
        bytes4 expectedIAccessControl = type(C).interfaceId; // dummy to compile? adjust below

        // We cannot refer to IAccessControl type directly here since C is imported; however
        // the interface id for IAccessControl equals the selector set declared in the reference.
        // Compute it by recreating the IAccessControl interface id via its function selectors.
        // IAccessControl has functions: hasRole(bytes32,address), getRoleAdmin(bytes32),
        // grantRole(bytes32,address), revokeRole(bytes32,address), renounceRole(bytes32,address)
        bytes4 s1 = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 s2 = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 s3 = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 s4 = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 s5 = bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 ia = s1 ^ s2 ^ s3 ^ s4 ^ s5;

        // Single assertion: when the fuzzed interfaceId equals the IAccessControl interface id,
        // the reference contract must report true via supportsInterface. This holds for the
        // correct contract for all inputs; the mutant (which always returns false) will fail
        // for that particular interface id found by the fuzzer.
        if (interfaceId == ia) {
            assertTrue(ok);
